    "text": "package rpc

import (
	"container/heap"
	"context"
	"errors"
	"time"

	"github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
)

// requestEntry belongs to the service queue until unlinkLocked transfers it to
// an executor or expiry owner. Link and watcher fields are protected by Service.mu.
type requestEntry struct {
	// serviceTask shares the admitted request with the executor without a second
	// allocation or ownership copy. It is submitted only after FIFO removal.
	serviceTask
	prev, next *requestEntry
	queued     bool
	// deadlineIndex is -1 outside the caller deadline heap; Service.mu owns it.
	deadlineIndex int
	enqueuedAt    time.Time
	// stopExpiry detaches cancellation from the original request context.
	stopExpiry func() bool
}

// watchQueue avoids a child context and its cancellation tree for a deadline
// used only by the FIFO. Service.mu serializes registration, dequeue, and expiry.
func (e *requestEntry) watchQueue(s *Service) {
	ctx := e.req.Context
	if ctx != s.ctx && ctx.Done() != nil {
		// Inbound requests already have an explicit cancellation
		// owner. Reuse its single queue hook instead of allocating a child
		// cancellation tree. Generic contexts retain the standard path.
		callback := func() { e.service.expire(e, requestError(e.req.Context.Err())) }
		if owner, ok := ctx.(interface{ WatchQueueCancellation(func()) func() bool }); ok {
			e.stopExpiry = owner.WatchQueueCancellation(callback)
		} else {
			e.stopExpiry = context.AfterFunc(ctx, callback)
		}
	}
}

func (e *requestEntry) stopQueueWatch() {
	if e.stopExpiry != nil {
		e.stopExpiry()
	}
}

func (s *Service) appendLocked(e *requestEntry) {
	e.prev = s.tail
	if s.tail != nil {
		s.tail.next = e
	} else {
		s.head = e
	}
	s.tail = e
	s.queuedItems++
	s.queuedBytes += e.req.retainedBytes
	s.queueRevision = core.NextStateRevision()
	if _, ok := e.req.Context.(interface{ WatchQueueCancellation(func()) func() bool }); ok {
		if _, hasDeadline := e.req.Context.Deadline(); hasDeadline {
			heap.Push(&s.callerDeadlines, e)
		}
	}
	if s.head == e || e.deadlineIndex == 0 {
		s.armQueueTimerLocked()
	}
}

func (s *Service) unlinkLocked(e *requestEntry) {
	wasHead := s.head == e
	wasEarliest := e.deadlineIndex == 0
	if e.deadlineIndex >= 0 {
		heap.Remove(&s.callerDeadlines, e.deadlineIndex)
	}
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		s.head = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		s.tail = e.prev
	}
	e.prev = nil
	e.next = nil
	e.queued = false
	s.queuedItems--
	s.queuedBytes -= e.req.retainedBytes
	s.queueRevision = core.NextStateRevision()
	if wasHead || wasEarliest {
		s.armQueueTimerLocked()
	}
}

// nextQueueDeadlineLocked combines FIFO service deadlines with out-of-order
// caller deadlines. Generic contexts still expire through context.AfterFunc.
func (s *Service) nextQueueDeadlineLocked() (*requestEntry, time.Time) {
	if s.stopped {
		return nil, time.Time{}
	}
	var selected *requestEntry
	var deadline time.Time
	if e := s.head; e != nil && s.opts.QueueTimeout > 0 {
		qd := e.enqueuedAt.Add(s.opts.QueueTimeout)
		caller, ok := e.req.Context.Deadline()
		if !ok || qd.Before(caller) {
			selected, deadline = e, qd
		}
	}
	if len(s.callerDeadlines) > 0 {
		e := s.callerDeadlines[0]
		d, _ := e.req.Context.Deadline()
		if selected == nil || d.Before(deadline) {
			selected, deadline = e, d
		}
	}
	return selected, deadline
}

// armQueueTimerLocked keeps one timer per service, regardless of queue length.
func (s *Service) armQueueTimerLocked() {
	e, deadline := s.nextQueueDeadlineLocked()
	if e != nil {
		delay := time.Until(deadline)
		if s.queueTimer == nil {
			s.queueTimer = time.AfterFunc(delay, s.expireQueueDeadline)
		} else {
			s.queueTimer.Reset(delay)
		}
	} else if s.queueTimer != nil {
		s.queueTimer.Stop()
	}
}

// expireQueueDeadline rechecks the current earliest deadline so a callback
// already running during Stop or Reset cannot expire a replacement early.
func (s *Service) expireQueueDeadline() {
	s.mu.Lock()
	e, deadline := s.nextQueueDeadlineLocked()
	if e == nil {
		s.mu.Unlock()
		return
	}
	if time.Now().Before(deadline) {
		s.armQueueTimerLocked()
		s.mu.Unlock()
		return
	}
	err := core.ErrTimeout
	if contextErr := e.req.Context.Err(); contextErr != nil {
		err = requestError(contextErr)
	}
	s.mu.Unlock()
	s.expire(e, err)
}

// expire releases both the FIFO position and payload even while all workers are blocked.
func (s *Service) expire(e *requestEntry, err error) {
	s.mu.Lock()
	if !e.queued {
		s.mu.Unlock()
		return
	}
	s.unlinkLocked(e)
	if s.stopped {
		err = core.ErrStopped
	}
	e.stopQueueWatch()
	event := s.queueEvent("expired", s.queueSnapshotLocked())
	s.mu.Unlock()
	s.observe(event)
	deliver(e.req, Response{Err: err})
	s.releaseRequest(e.req)
}

func (s *Service) nextRequest() (Request, bool) {
	for {
		s.mu.Lock()
		if s.stopped {
			s.mu.Unlock()
			return Request{}, false
		}
		e := s.head
		if e != nil {
			s.unlinkLocked(e)
			err := s.beforeExecution(e.req)
			e.stopQueueWatch()
			event := s.queueEvent("ok", s.queueSnapshotLocked())
			s.mu.Unlock()
			s.observe(event)
			if err != nil {
				deliver(e.req, Response{Err: err})
				s.releaseRequest(e.req)
				continue
			}
			return e.req, true
		}
		s.mu.Unlock()
		select {
		case <-s.ctx.Done():
			return Request{}, false
		case <-s.queueReady:
		}
	}
}

func requestError(err error) error {
	if errors.Is(err, context.DeadlineExceeded) {
		return core.ErrTimeout
	}
	if errors.Is(err, context.Canceled) {
		return core.ErrCanceled
	}
	return err
}
