new file mode 100644
index 000000000..20b5e23f5
--- /dev/null
+++ b/pkg/transport/internal/rpc/caller_deadline.go
@@ -0,0 +1,32 @@
+package rpc
+
+// callerDeadlineQueue is a queue-bounded min-heap. The intrusive FIFO retains
+// dispatch order; the heap only chooses which waiting owner may expire first.
+// All methods run under Service.mu and removal clears retained owner pointers.
+type callerDeadlineQueue []*requestEntry
+
+func (q callerDeadlineQueue) Len() int { return len(q) }
+func (q callerDeadlineQueue) Less(i, j int) bool {
+	a, _ := q[i].req.Context.Deadline()
+	b, _ := q[j].req.Context.Deadline()
+	return a.Before(b)
+}
+func (q callerDeadlineQueue) Swap(i, j int) {
+	q[i], q[j] = q[j], q[i]
+	q[i].deadlineIndex = i
+	q[j].deadlineIndex = j
+}
+func (q *callerDeadlineQueue) Push(v any) {
+	e := v.(*requestEntry)
+	e.deadlineIndex = len(*q)
+	*q = append(*q, e)
+}
+func (q *callerDeadlineQueue) Pop() any {
+	old := *q
+	n := len(old) - 1
+	e := old[n]
+	old[n] = nil
+	e.deadlineIndex = -1
+	*q = old[:n]
+	return e
+}
