+	"testing/synctest"
+	"time"
+
+	"github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
+)
+
+// A queue-owned deadline remains authoritative even if its context timer has
+// not run yet. Explicit cancellation still uses the supplied detachable hook.
+type queueDeadlineContext struct {
+	context.Context
+	deadline time.Time
+}
+
+func (c queueDeadlineContext) Deadline() (time.Time, bool) { return c.deadline, true }
+func (c queueDeadlineContext) WatchQueueCancellation(f func()) func() bool {
+	return context.AfterFunc(c.Context, f)
+}
+
+func TestCallerDeadlineExpiresNonHeadAndRearms(t *testing.T) {
+	synctest.Test(t, func(t *testing.T) {
+		root, cancel := context.WithCancel(context.Background())
+		defer cancel()
+		s := &Service{ctx: root, cancel: cancel, opts: normalizeServiceOptions(core.ServiceOptions{QueueSize: 4, MaxQueueBytes: 1024, QueueTimeout: time.Hour}), queueReady: make(chan struct{}, 1), done: make(chan struct{})}
+		defer s.Stop()
+		enqueue := func(delay time.Duration) (chan Response, context.CancelFunc) {
+			parent, stop := context.WithCancel(context.Background())
+			reply := make(chan Response, 1)
+			if err := s.Enqueue(Request{Context: queueDeadlineContext{parent, time.Now().Add(delay)}, Reply: reply}); err != nil {
+				t.Fatal(err)
+			}
+			return reply, stop
+		}
+		long, stopLong := enqueue(time.Hour)
+		defer stopLong()
+		short, stopShort := enqueue(time.Second)
+		defer stopShort()
+		middle, stopMiddle := enqueue(2 * time.Second)
+		defer stopMiddle()
+		time.Sleep(time.Second)
+		synctest.Wait()
+		select {
+		case r := <-short:
+			if !errors.Is(r.Err, core.ErrTimeout) {
+				t.Fatal(r.Err)
+			}
+		default:
+			t.Fatal("non-head caller deadline did not release its admission")
+		}
+		select {
+		case <-long:
+			t.Fatal("FIFO head expired early")
+		default:
+		}
+		// Cancel the remaining earlier deadline and reuse its slot with a later one.
+		stopMiddle()
+		synctest.Wait()
+		select {
+		case r := <-middle:
+			if !errors.Is(r.Err, core.ErrCanceled) {
+				t.Fatal(r.Err)
+			}
+		default:
+			t.Fatal("explicit cancellation did not finish")
+		}
+		fresh, stopFresh := enqueue(3 * time.Second)
+		defer stopFresh()
+		time.Sleep(time.Second)
+		s.expireQueueDeadline()
+		synctest.Wait()
+		select {
+		case <-fresh:
+			t.Fatal("stale deadline callback expired a replacement")
+		default:
+		}
+		time.Sleep(2 * time.Second)
+		synctest.Wait()
+		select {
+		case r := <-fresh:
+			if !errors.Is(r.Err, core.ErrTimeout) {
+				t.Fatal(r.Err)
+			}
+		default:
+			t.Fatal("replacement deadline was not rearmed")
+		}
+		s.mu.Lock()
+		queued, retained, deadlines := s.queuedItems, s.retainedItems, len(s.callerDeadlines)
+		s.mu.Unlock()
+		if queued != 1 || retained != 1 || deadlines != 1 {
+			t.Fatalf("remaining ownership: queued=%d retained=%d deadlines=%d", queued, retained, deadlines)
+		}
+		s.Stop()
+		s.mu.Lock()
+		defer s.mu.Unlock()
+		if len(s.callerDeadlines) != 0 {
+			t.Fatal("stop retained caller deadlines")
+		}
+		for _, e := range s.callerDeadlines[:cap(s.callerDeadlines)] {
+			if e != nil {
+				t.Fatal("removed deadline retained an owner")
+			}
+		}
+	})
+}

