//go:build integration

package rpc

import (
 "context"
 "testing"
 "time"
 "github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
)

// BenchmarkLifecycleStages measures cumulative real queue/handler operations.
// It deliberately omits transport encoding and service/executor scheduling.
func BenchmarkLifecycleStages(b *testing.B) {
 for _, budget:=range []bool{false,true} {
  bn:="no_budget";if budget {bn="budget"}
