out={}
for batch in ['controls','allocation','overload','overload-allocation']:
 rows=json.loads((E/(batch+'.json')).read_text())
 groups={}
 for r in rows:
  scenario=re.sub(r'-[12]-shards.*','',r['label']) if batch=='controls' else batch
  key=scenario+'/shards'+str(r['result']['shards'])
  groups.setdefault(key,[]).append(r)
 out[batch]={}
 for key,rs in groups.items():
  metrics=['calls_per_second','p99_ms'];alloc='allocation' in batch
  if alloc:metrics+=['bytes_per_call','allocs_per_call']
  def value(r,m):return r['result']['server_allocation'][m] if m.endswith('_per_call') else r['result'][m]
  d={'medians':{},'pairs':[]}
  for version in ['base','candidate']:
   rr=[r for r in rs if r['server'].startswith(version)]
   d['medians'][version]={m:statistics.median(value(r,m) for r in rr) for m in metrics}
  d['changes']={m:100*(d['medians']['candidate'][m]/d['medians']['base'][m]-1) for m in metrics}
  d['absolute_changes']={m:d['medians']['candidate'][m]-d['medians']['base'][m] for m in metrics}
  for i in range(0,len(rs),2):
   a=next(r for r in rs[i:i+2] if r['server'].startswith('base'));b=next(r for r in rs[i:i+2] if r['server'].startswith('candidate'))
   d['pairs'].append({m:100*(value(b,m)/value(a,m)-1) for m in metrics})
  out[batch][key]=d
