from pathlib import Path
import json,statistics,re,sys
E=Path(__file__).resolve().parent;batch=sys.argv[1] if len(sys.argv)>1 else 'timing';rows=json.loads((E/(batch+'.json')).read_text())
out={'windows':len(rows),'successful_calls':sum(r['result']['calls'] for r in rows),'shards':{}}
def cpu(r):
 def use(s):return int(re.search(r'^usage_usec (\d+)$',s,re.M).group(1))
 return (use(r['runtime_state_after'])-use(r['runtime_state_before']))/r['result']['calls']
for shards in [1,16]:
 paired=[r for r in rows if r['result']['shards']==shards and not r['label'].startswith('aa-')]
 d={'medians':{},'pairs':[],'aa':{}}
 for v in ['base','candidate']:
  rr=[r for r in paired if r['server']==v]
  if rr:
   d['medians'][v]={k:statistics.median(r['result'][k] for r in rr) for k in ['calls_per_second','p99_ms']}
   d['medians'][v]['cpu_envelope_us_per_call']=statistics.median(cpu(r) for r in rr)
  aa=[r for r in rows if r['server']==v and r['result']['shards']==shards and r['label'].startswith('aa-')]
  if len(aa)==2:d['aa'][v]={k:100*(aa[1]['result'][k]/aa[0]['result'][k]-1) for k in ['calls_per_second','p99_ms']}
 for i in range(0,len(paired)-1,2):
  a=next(r for r in paired[i:i+2] if r['server']=='base');b=next(r for r in paired[i:i+2] if r['server']=='candidate')
  d['pairs'].append({k:100*(b['result'][k]/a['result'][k]-1) for k in ['calls_per_second','p99_ms']})
 if len(d['medians'])==2:d['changes']={k:100*(d['medians']['candidate'][k]/d['medians']['base'][k]-1) for k in d['medians']['base']}
 out['shards'][str(shards)]=d
(E/(batch+'-summary.json')).write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))

