//go:build integration

package conn

import (
 "context"
 "testing"
 "time"
 "github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
 "github.com/WuKongIM/WuKongIM/pkg/transport/internal/rpc"
)

// BenchmarkInboundLifecycle includes real request tracking and, in full mode,
// service admission, queue cancellation, executor work, and terminal cleanup.
func BenchmarkInboundLifecycle(b *testing.B) {
 for _, budget:=range []bool{false,true} {
  bn:="no_budget";if budget {bn="budget"}
  b.Run(bn,func(b *testing.B){
   for _, stage:=range []string{"tracking","mutation","read"} {
    b.Run(stage,func(b *testing.B){
     ctx,cancel:=context.WithCancel(context.Background());defer cancel()
     c:=&Conn{ctx:ctx}
     completed:=make(chan struct{},1)
     var finish func()
     done:=func(){finish();completed<-struct{}{}}
     var s *rpc.Service
     if stage!="tracking" {
      s=rpc.NewService(1,func(context.Context,[]byte)([]byte,error){return nil,nil},core.ServiceOptions{Concurrency:1,QueueSize:1,MaxQueueBytes:64,Timeout:30*time.Second,QueueTimeout:5*time.Second,CancelRunning:stage=="read"},nil)
      defer s.Stop()
     }
     payload:=core.NewOwnedBuffer([]byte("work"),nil)
     call:=func(){
      d:=time.Duration(0);if budget {d=2*time.Second}
      rc,f,err:=c.TrackInbound(1,d);if err!=nil {b.Fatal(err)}
      if s==nil {select {case <-rc.Done():b.Fatal("unexpected expiry");default:};f();return}
      finish=f
      if err:=s.Enqueue(rpc.Request{Context:rc,Finish:done,Payload:payload});err!=nil {f();b.Fatal(err)}
      <-completed
     }
     for i:=0;i<100;i++ {call()}
     b.ReportAllocs();b.ResetTimer()
     for i:=0;i<b.N;i++ {call()}
    })
   }
  })
 }
}

